import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a right triangle APM with right angle at A, a circle of radius {radius} is drawn with center O on segment AP so that it is tangent to segments AM and PM. The triangle’s perimeter is {perimeter}. It is further known that this perimeter has the special form 2k^2·r/(k−1) with k={k} and r={radius}. If OP can be expressed as m/n in lowest terms, find m+n.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We construct instances so that S = 2 k^2 r/(k-1) and OP is a non-integer reduced fraction.
# Choose k >= 3 and t >= 2 with gcd(t, k+1) = 1, set r = (k-1)*t and S = 2*k^2*t.
# This ensures the circle exists and yields OP = t*(k^2+1)/(k+1), which is non-integer because gcd(t, k+1) = 1.
import math
for _ in range(200):
    k = rng.randint(3, 30)
    t = rng.randint(2, 300)
    if math.gcd(t, k+1) != 1:
        continue
    radius = (k - 1) * t
    perimeter = 2 * (k ** 2) * t
    # Extra guard: ensure OP denominator > 1 and not trivially small
    num = t * (k * k + 1)
    den = k + 1
    g = math.gcd(num, den)
    m = num // g
    n = den // g
    if n <= 1:
        continue
    # Also avoid extremely small answers and overly huge numbers
    if m + n < 10:
        continue
    return {'radius': radius, 'k': k, 'perimeter': perimeter}
# Fallback deterministic construction if random attempts fail
k = 7
t = 5
radius = (k - 1) * t
perimeter = 2 * (k ** 2) * t
return {'radius': radius, 'k': k, 'perimeter': perimeter}

    def verifier(assign):
# Verifies the structural constraints and computes the unique correct answer.
# Geometry model and derivation:
# Place A=(0,0), P=(x,0), M=(0,y). Tangency to AM forces O=(r,0), with r=assign['radius'].
# Tangency to PM gives y(x-r) = r * sqrt(x^2 + y^2); perimeter S = x + y + sqrt(x^2 + y^2).
# Eliminating sqrt yields the cubic 2 y^3 - (S - 2 r) y^2 + r^2 S = 0.
# For the special choice S = 2 k^2 r/(k-1) (encoded here by r=(k-1)*t and S=2 k^2 t), the positive root is y = k r.
# Then x = S/(k+1), and OP = x - r = t * (k^2 + 1)/(k + 1).
import math
try:
    r = int(assign['radius'])
    k = int(assign['k'])
    S = int(assign['perimeter'])
except Exception:
    # Missing or invalid types
    return (False, None)
# Basic domain checks
if r <= 0 or k < 3 or S <= 0:
    return (False, None)
# Ensure r is a multiple of (k-1) so that S is of the form 2 k^2 r/(k-1) with integer S
if r % (k - 1) != 0:
    # The instance would not match the intended parametric family
    return (False, None)
t = r // (k - 1)
# Verify the perimeter matches the construction S = 2 k^2 t
if S != 2 * (k ** 2) * t:
    return (False, None)
# Enforce non-triviality: OP is not an integer and denominator > 1
if math.gcd(t, k + 1) != 1:
    # If gcd(t, k+1) > 1, the fraction may reduce too far; we avoid trivialities
    return (False, None)
# Compute OP = t * (k^2 + 1) / (k + 1) and reduce to lowest terms
num = t * (k * k + 1)
den = k + 1
g = math.gcd(num, den)
m = num // g
n = den // g
if n <= 1:
    # Integer or degenerate fraction not allowed; intended family enforces n >= 2
    return (False, None)
answer = m + n
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

